DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.activity_workspace(date,uuid,text,boolean)'::regprocedure) INTO f; f:=replace(f,'''owner_id'',t.owner_id,''backup_id'',t.backup_id','''owner_id'',t.owner_id,''backup_id'',t.backup_id,''people'',coalesce((SELECT jsonb_agg(jsonb_build_object(''id'',a.user_id,''name'',pr.full_name)) FROM client_staff_assignments a JOIN profiles pr ON pr.id=a.user_id AND pr.status=''active'' WHERE a.client_id=cp.client_id AND a.pipeline_id=cp.pipeline_id AND NOT a.excluded),''[]''::jsonb)'); EXECUTE f; END $$;